import{_ as e,o as s,c as i,ag as o}from"./chunks/framework.D9ghT4bC.js";const f=JSON.parse('{"title":"概述","description":"","frontmatter":{"title":"概述"},"headers":[],"relativePath":"zh/Modders/Mod-file-structure/1-Overview.md","filePath":"zh/Modders/Mod-file-structure/1-Overview.md"}'),l={name:"zh/Modders/Mod-file-structure/1-Overview.md"};function r(d,t,a,n,u,c){return s(),i("div",null,[...t[0]||(t[0]=[o(`<h1 id="模组文件结构概述" tabindex="-1">模组文件结构概述 <a class="header-anchor" href="#模组文件结构概述" aria-label="Permalink to &quot;模组文件结构概述&quot;">​</a></h1><p>这些页面正在开发中。它们包含的信息可能不完整。</p><p>组成模组的 JSON 文件可以有许多不同的字段，由于并非所有字段都在基础游戏中使用，此 wiki 页面将包含每个字段的完整信息。它还将提供 JSON 文件语法的简要说明。</p><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ul><li><a href="#json-文件总览">JSON 文件总览</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html">文明相关 JSON 文件</a><ul><li><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#beliefsjson">Beliefs.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#buildingsjson">Buildings.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#citystatetypesjson">CityStateTypes.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#nationsjson">Nations.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#policiesjson">Policies.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#questsjson">Quests.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#religionsjson">Religions.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#specialistsjson">Specialists.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#techsjson">Techs.json</a></li></ul></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html">地图相关 JSON 文件</a><ul><li><a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#terrainsjson">Terrains.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#tileresourcesjson">TileResources.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#tileimprovementsjson">TileImprovements.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#ruinsjson">Ruins.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#地形集专用-json">地形集专用 json</a></li></ul></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/4-Unit-related-JSON-files.html">单位相关 JSON 文件</a><ul><li><a href="/Unciv/zh/Modders/Mod-file-structure/4-Unit-related-JSON-files.html#unitsjson">Units.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/4-Unit-related-JSON-files.html#unitpromotionsjson">UnitPromotions.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/4-Unit-related-JSON-files.html#unittypesjson">UnitTypes.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/4-Unit-related-JSON-files.html#unitnamegroupsjson">UnitNameGroups.json</a></li></ul></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html">其他 JSON 文件</a><ul><li><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#difficultiesjson">Difficulties.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#erasjson">Eras.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#modoptionsjson">ModOptions.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#globaluniquesjson">GlobalUniques.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#speedsjson">Speeds.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#tutorialsjson">Tutorials.json</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#victorytypesjson">VictoryTypes.json</a></li></ul></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#统计">统计</a></li><li><a href="/Unciv/zh/Modders/Images-and-Audio.html#声音">声音</a></li><li><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#civilopedia-文本">Civilopedia 文本</a></li></ul><h2 id="json-文件总览" tabindex="-1">JSON 文件总览 <a class="header-anchor" href="#json-文件总览" aria-label="Permalink to &quot;JSON 文件总览&quot;">​</a></h2><p><strong>推荐阅读</strong>：<a href="https://www.json.org/" target="_blank" rel="noreferrer">json.org</a>，<a href="https://standards.iso.org/ittf/PubliclyAvailableStandards/c071616_ISO_IEC_21778_2017.zip" target="_blank" rel="noreferrer">ISO 标准</a></p><p>几乎所有 Unciv JSON 文件都以 &quot;[&quot; 开头，以 &quot;]&quot; 结尾。在这两者之间是你正在描述的不同类型的对象，每个对象都包含在 &quot;{&quot; 和 &quot;}&quot; 之间。例如，一个非常简单的 units.json 可能看起来像这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;name&quot;: &quot;Warrior&quot;,</span></span>
<span class="line"><span>        &quot;cost&quot;: 16</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;name&quot;: &quot;Spearman&quot;,</span></span>
<span class="line"><span>        &quot;cost&quot;: 24,</span></span>
<span class="line"><span>        &quot;promotions&quot;: [&quot;Shock I&quot;, &quot;Drill I&quot;]</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>]</span></span></code></pre></div><p>此文件包含两个单位对象，一个用于战士，一个用于枪兵。这些对象具有不同的属性，在这种情况下是&quot;name&quot;、&quot;cost&quot;和&quot;promotions&quot;。所有这些属性都有一定的类型，&quot;name&quot;的字符串（文本），&quot;cost&quot;的整数，&quot;promotions&quot;的字符串列表。</p><p>有不同类型的属性：</p><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>String</td><td>一个单词或句子。应该在双引号（&quot;）之间，并转义作为文本一部分的双引号：<code>\\&quot;</code></td></tr><tr><td>Integer</td><td>一个数字。可以是正数或负数。应该<strong>不</strong>在引号之间</td></tr><tr><td>Float</td><td>一个可以有小数位的数字。请记住使用 <code>.</code> 作为 JSON 标准需要的，而不是你本地文化的小数符号。科学计数法也可以工作，虽然</td></tr><tr><td>Boolean</td><td>可以是&#39;true&#39;或&#39;false&#39;的值。应该<strong>不</strong>在引号之间</td></tr><tr><td>List of [type]</td><td>如果可以应用多个值（如上面的晋升），它们应该放在列表中。列表的每个元素应该像普通属性一样编写，用逗号分隔，并包含在方括号之间。例如：[&quot;Shock I&quot;, &quot;Shock II&quot;] 或 [1, 2, 3]。</td></tr><tr><td>Object</td><td>最复杂的属性类型。对象由多个属性组成，每个属性又有一个类型。这些属性有一个键（&quot;:&quot;之前的部分）和一个值（它后面的部分）。有关示例，请参见下文。</td></tr></tbody></table><p>添加一个新的&quot;Cultural Library&quot;建筑（提供 +50% 科技和 +50% 文化）的 Buildings.json 示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;name&quot;: &quot;Cultural Library&quot;</span></span>
<span class="line"><span>        &quot;percentStatBonus&quot; : {&quot;science&quot;: 50, &quot;culture&quot;: 50}</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>]</span></span></code></pre></div><p>在此示例中，键是&quot;science&quot;和&quot;culture&quot;，两者的值都是&quot;50&quot;。</p><p>在某种意义上，你可以从这些类型中看到 JSON 文件本身实际上是一个对象列表，每个对象描述一个建筑、单位或其他东西。</p><h2 id="基础规则集要求" tabindex="-1">基础规则集要求 <a class="header-anchor" href="#基础规则集要求" aria-label="Permalink to &quot;基础规则集要求&quot;">​</a></h2><p>基础规则集模组本身必须是&quot;完整的&quot;，但这并不意味着它们必须包含所有可能的 JSON 文件或在所有文件中定义内容。这是一个细分（WIP，可能不准确）：</p><table tabindex="0"><thead><tr><th>文件</th><th>允许为空？</th><th>默认/回退</th></tr></thead><tbody><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#beliefsjson">Beliefs</a></td><td>是</td><td>无</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#buildingsjson">Buildings</a></td><td>否</td><td>无</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#citystatetypesjson">CityStateTypes</a></td><td>否</td><td>原版</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#difficultiesjson">Difficulties</a></td><td>否</td><td>原版</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#erasjson">Eras</a></td><td>否</td><td>无</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#globaluniquesjson">GlobalUniques</a></td><td>是</td><td>原版</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#modoptionsjson">ModOptions</a></td><td>是</td><td>下载时生成</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#nationsjson">Nations</a></td><td>否</td><td>无</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#policiesjson">Policies</a></td><td>是</td><td>无</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#questsjson">Quests</a></td><td>是</td><td>无</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#religionsjson">Religions</a></td><td>是</td><td>无</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#ruinsjson">Ruins</a></td><td>是</td><td>原版</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#specialistsjson">Specialists</a></td><td>是</td><td>无</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#speedsjson">Speeds</a></td><td>否</td><td>原版</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#techsjson">Techs</a></td><td>是</td><td>无</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#terrainsjson">Terrains</a></td><td>否</td><td>无</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#tileimprovementsjson">TileImprovements</a></td><td>是</td><td>无</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#tileresourcesjson">TileResources</a></td><td>是</td><td>无</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#tutorialsjson">Tutorials</a></td><td>是</td><td>内置始终显示</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/4-Unit-related-JSON-files.html#unitpromotionsjson">UnitPromotions</a></td><td>是</td><td>无</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/4-Unit-related-JSON-files.html#unitsjson">Units</a></td><td>否</td><td>无</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/4-Unit-related-JSON-files.html#unittypesjson">UnitTypes</a></td><td>否</td><td>原版</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#victorytypesjson">VictoryTypes</a></td><td>否</td><td>原版</td></tr></tbody></table><ul><li>模组加载永远不会因缺少文件而失败，它们首先默认为空。然后仅对基础规则集应用上述回退。该步骤之后的不一致性将由模组检查器报告。</li><li>GlobalUniques 有一个在文件缺失时使用的回退。因此，模组可以通过包含空内容（<code>{}</code>）来有意定义没有回退。</li><li>Ruins 有一个在文件缺失时使用的回退。因此，模组可以通过包含空内容（<code>[]</code>）来有意定义没有回退。</li></ul><h2 id="uniques" tabindex="-1">Uniques <a class="header-anchor" href="#uniques" aria-label="Permalink to &quot;Uniques&quot;">​</a></h2><p>&quot;Uniques&quot;是 Unciv 用于可扩展和可自定义效果的标签。几乎每个&quot;规则集对象&quot;都允许一组它们，作为名为&quot;uniques&quot;的列表。</p><p>每个 Unique 遵循一般结构：<code>Unique 类型定义名称 [占位符] 更多名称 [另一个占位符] &lt;条件或触发器&gt; &lt;条件或触发器&gt;...</code> 整个字符串，排除所有用 <code>&lt;&gt;</code> 分隔的条件或触发器及其分隔空格，以及排除占位符但不排除其 <code>[]</code> 分隔符，用于查找 Unique 的实现。 可选 <code>[占位符]</code> 的内容取决于实现，它们是修改效果的参数，并在 <a href="/Unciv/zh/Modders/Unique-parameters.html">Unique 参数</a>中描述。 所有 <code>&lt;条件或触发器&gt;</code> 都是可选的（但如果使用它们，分隔它们的空格是强制性的），并且每个依次遵循 <code>&lt;&gt;</code> 尖括号之间部分的 Unique 结构规则，包括可能的占位符，但不包括嵌套条件。</p><p>示例：建筑上的 <code>&quot;uniques&quot;:[&quot;[+1 Gold] &lt;with a garrison&gt;&quot;]</code> - 与 <code>&quot;gold&quot;:1</code> 属性的作用几乎相同，除了它仅在城市有驻军时适用。在此示例中，<code>[]</code> 和 <code>with a garrison</code> 是 Unciv 用于查找两个 Uniques 的键，一个是效果（类型为 <code>Stats</code>），一个是条件（类型为 <code>ConditionalWhenGarrisoned</code>）。</p><p>Unciv 中有实现的所有 Unique&quot;类型&quot;都会自动记录在 <a href="/Unciv/zh/Modders/uniques.html">Uniques</a>中。请注意，该文件完全是从源代码结构生成的。还要注意 <a href="/Unciv/zh/Modders/uniques.html#条件-uniques">条件</a>和 <a href="/Unciv/zh/Modders/uniques.html#触发条件-uniques">触发条件</a> 的单独章节。 与这些条目中的任何一个都不对应的 Uniques（逐字包括大小写！）被称为&quot;无类型&quot;，将没有<strong>直接</strong>效果，并可能导致&quot;规则集验证器&quot;显示警告（请参阅选项选项卡&quot;定位模组错误&quot;，它在开始新游戏时也会运行）。 &quot;无类型&quot;Uniques 的合法用途是它们作为可以在<strong>过滤器</strong>中其他地方识别的标记（示例：原版规则集中的&quot;Aircraft&quot;用作<a href="/Unciv/zh/Modders/Unique-parameters.html#baseunitfilter">单位过滤器</a>）。 此用途被&quot;规则集验证器&quot;识别，并且不会被标记为无效 - 但过滤 Unique 必须也<strong>不使用占位符或条件</strong>才能通过测试。 如果你收到&quot;未在 Unciv 的 unique 类型中找到&quot;警告，但确定你使用的是正确的过滤 Unique，请在所有地方查找完全相同的拼写，包括大小写。 注意：目前一些模组使用无类型 Uniques 不是为了过滤目的，而是作为纯信息工具。团队将尝试为此用途考虑一种方法，该方法不会在不降低验证质量的情况下触发验证警告，但截至目前，这些是不可避免的。</p><h2 id="游戏中使用的-json-文件信息" tabindex="-1">游戏中使用的 JSON 文件信息 <a class="header-anchor" href="#游戏中使用的-json-文件信息" aria-label="Permalink to &quot;游戏中使用的 JSON 文件信息&quot;">​</a></h2><p>Unciv 的许多部分都是可模组化的，每个部分都有一个单独的 json 文件。有一个建筑的 json 文件，一个单位的 json 文件，一个单位可以拥有的晋升的 json 文件，一个科技的 json 文件等等。你定义的不同新建筑或单位也可以有许多不同的属性，尽管并非所有属性都是必需的。以下是记录所有内容可以拥有的所有不同属性的表格。只有标记为&quot;必需&quot;的属性必须提供。所有其他属性都有一个默认值，在省略时将使用。</p><p>各个文件在<a href="#目录">单独的页面</a>上描述。</p>`,28)])])}const p=e(l,[["render",r]]);export{f as __pageData,p as default};
